// Generated by LCD Wizard - helpers used by conversion formulas

#pragma once

#include <math.h>

static inline float _lw_mapf(float x, float inMin, float inMax, float outMin, float outMax)
{
    if (inMax == inMin) return outMin;
    return (x - inMin) * (outMax - outMin) / (inMax - inMin) + outMin;
}

static inline float _lw_clampf(float x, float lo, float hi)
{
    return x < lo ? lo : (x > hi ? hi : x);
}
